"""Teacher scoring for teachers whose tokenizer differs from the student's.

Ported from THUDM/slime PR #2032 ("Support OPD when teacher tokenization differs", 76fde4feb,
slime/rollout/on_policy_distillation.py: reward_func_cross_vocab / post_process_rewards_cross_vocab) onto our
Miles stack and extended for multi-turn agent episodes across model families:
  - settings come from the run's --custom-config-path YAML (teacher_tokenizer_path, opd_prompt_messages_key,
    opd_teacher_chat_template_kwargs, opd_teacher_timeout / _retries / _concurrency);
  - same-tokenizer teachers (e.g. Qwen3.5-9B for a Qwen3.5-2B student) are detected by comparing vocabularies so
    reward.py routes them through the exact token-id OPD path;
  - each assistant turn in sample.metadata["messages"] (and metadata["tools"]) is rendered as the teacher sees the
    conversation up to that turn, scored by the teacher, and aligned at the UTF-8 byte level onto the student's
    writing segments (reasoning_content, content, and native tool_call names/arguments);
  - the verdict reward is kept by examples/terminal_opd/reward.py, this module only fills teacher_log_probs.
"""

import asyncio
import json
import logging
import math
import os
from typing import Any

import aiohttp
import torch

from miles.rollout import on_policy_distillation as opd
from miles.utils.types import Sample

logger = logging.getLogger(__name__)


def _bytes_to_unicode() -> dict[str, int]:
    bs = (
        list(range(ord("!"), ord("~") + 1))
        + list(range(ord("¡"), ord("¬") + 1))
        + list(range(ord("®"), ord("ÿ") + 1))
    )
    cs = bs[:]
    n = 0
    for b in range(256):
        if b not in bs:
            bs.append(b)
            cs.append(256 + n)
            n += 1
    return {chr(c): b for b, c in zip(bs, cs, strict=True)}


_B2U = _bytes_to_unicode()


def _build_token_bytes_table(tokenizer) -> list[bytes]:
    vocab = tokenizer.get_vocab()
    added = getattr(tokenizer, "added_tokens_decoder", {}) or {}
    added_ids = {int(k): v.content.encode("utf-8") for k, v in added.items()}
    max_id = max(max(vocab.values(), default=0), max(added_ids.keys(), default=0))
    table = [b""] * (max_id + 1)
    for token_str, tid in vocab.items():
        if tid in added_ids:
            table[tid] = added_ids[tid]
        else:
            try:
                table[tid] = bytes(_B2U[c] for c in token_str)
            except KeyError:
                text = tokenizer.decode([tid], skip_special_tokens=False, clean_up_tokenization_spaces=False) or ""
                table[tid] = text.encode("utf-8")
    for tid, b in added_ids.items():
        table[tid] = b
    return table


def _token_bytes(tokenizer, table: list[bytes], tid: int) -> bytes:
    if 0 <= tid < len(table):
        return table[tid]
    text = tokenizer.decode([tid], skip_special_tokens=False, clean_up_tokenization_spaces=False) or ""
    return text.encode("utf-8")


def _same_tokenizer(student_tok, teacher_tok) -> bool:
    if student_tok.get_vocab() != teacher_tok.get_vocab():
        return False
    s_added = {int(k): v.content for k, v in (getattr(student_tok, "added_tokens_decoder", {}) or {}).items()}
    t_added = {int(k): v.content for k, v in (getattr(teacher_tok, "added_tokens_decoder", {}) or {}).items()}
    return s_added == t_added


def _load_cross_vocab_tokenizers(args) -> None:
    """Lazy-load teacher and student tokenizers and byte lookup tables, caching them on args."""
    if hasattr(args, "_cross_vocab_student_tok"):
        return

    teacher_path = getattr(args, "teacher_tokenizer_path", None)
    if not teacher_path:
        raise ValueError(
            "teacher_tokenizer_path is required for cross-vocabulary OPD. "
            "It must point to the teacher model tokenizer."
        )

    from transformers import AutoTokenizer

    student_tok = AutoTokenizer.from_pretrained(args.hf_checkpoint, trust_remote_code=True)
    teacher_tok = AutoTokenizer.from_pretrained(teacher_path, trust_remote_code=True)
    args._cross_vocab_student_tok = student_tok
    args._cross_vocab_teacher_tok = teacher_tok
    args._cross_vocab_is_cross = not _same_tokenizer(student_tok, teacher_tok)
    if args._cross_vocab_is_cross:
        args._cross_vocab_student_bytes = _build_token_bytes_table(student_tok)
        args._cross_vocab_teacher_bytes = _build_token_bytes_table(teacher_tok)


def is_cross_vocab(args) -> bool:
    """Return True iff teacher_tokenizer_path is set and its vocabulary differs from the student's."""
    if hasattr(args, "_cross_vocab_is_cross"):
        return bool(args._cross_vocab_is_cross)
    teacher_path = getattr(args, "teacher_tokenizer_path", None)
    if not teacher_path:
        args._cross_vocab_is_cross = False
        return False
    student_path = getattr(args, "hf_checkpoint", None)
    if student_path and os.path.abspath(str(teacher_path)) == os.path.abspath(str(student_path)):
        args._cross_vocab_is_cross = False
        return False
    _load_cross_vocab_tokenizers(args)
    return bool(args._cross_vocab_is_cross)


def _get_teacher_semaphore(args):
    loop = asyncio.get_running_loop()
    loop_key = id(loop)
    semaphores_by_loop = getattr(args, "_opd_teacher_semaphores", None)
    if semaphores_by_loop is None:
        semaphores_by_loop = {}
        args._opd_teacher_semaphores = semaphores_by_loop

    concurrency = int(getattr(args, "opd_teacher_concurrency", 0) or 0)
    if concurrency <= 0:
        return None

    semaphore = semaphores_by_loop.get(loop_key)
    if semaphore is None:
        semaphore = asyncio.Semaphore(concurrency)
        semaphores_by_loop[loop_key] = semaphore
    return semaphore


def _teacher_payload_summary(payload):
    if "input_ids" in payload:
        ids = payload["input_ids"]
        if ids and isinstance(ids[0], list):
            return f"batch={len(ids)} input_tokens={sum(len(x) for x in ids)}"
        return f"input_tokens={len(ids)}"
    if "text" in payload:
        return f"text_chars={len(payload['text'])}"
    return "payload_size=unknown"


async def _post_teacher_once(session, teacher_url, payload):
    async with session.post(teacher_url, json=payload) as resp:
        if resp.status >= 400:
            body = (await resp.text())[:500]
            raise aiohttp.ClientResponseError(
                request_info=resp.request_info,
                history=resp.history,
                status=resp.status,
                message=f"{resp.reason}; body={body}",
                headers=resp.headers,
            )
        return await resp.json()


async def _post_teacher_json(args, teacher_url, payload, sample, warning_prefix):
    retries = max(0, int(getattr(args, "opd_teacher_retries", 2)))
    timeout = aiohttp.ClientTimeout(total=float(getattr(args, "opd_teacher_timeout", 300.0)))
    semaphore = _get_teacher_semaphore(args)
    last_exc = None

    for attempt in range(retries + 1):
        try:
            async with aiohttp.ClientSession(timeout=timeout) as session:
                if semaphore is None:
                    return await _post_teacher_once(session, teacher_url, payload)
                async with semaphore:
                    return await _post_teacher_once(session, teacher_url, payload)
        except (TimeoutError, asyncio.TimeoutError, aiohttp.ClientError) as exc:
            last_exc = exc
            if attempt < retries:
                await asyncio.sleep(min(0.2 * (2**attempt), 2.0))
                continue

    logger.warning(
        "%s failed after %s attempt(s); using student rollout logprobs as teacher logprobs "
        "for sample index=%s (%s): %s: %s",
        warning_prefix,
        retries + 1,
        getattr(sample, "index", None),
        _teacher_payload_summary(payload),
        type(last_exc).__name__,
        last_exc,
    )
    return {"_opd_teacher_fallback": True, "_opd_teacher_fallback_reason": type(last_exc).__name__}


def _student_rollout_lps(sample: Sample) -> list[float]:
    resp_len = sample.response_length
    if resp_len <= 0:
        return []
    rollout_lps = sample.rollout_log_probs
    if rollout_lps is None:
        return [0.0] * resp_len
    if isinstance(rollout_lps, torch.Tensor):
        vals = rollout_lps.detach().cpu().to(torch.float32).flatten().tolist()
    else:
        vals = [float(x) for x in rollout_lps]
    if len(vals) >= resp_len:
        return vals[-resp_len:]
    return [0.0] * (resp_len - len(vals)) + vals


def _use_student_log_probs_for_teacher(sample: Sample, reason: str) -> None:
    resp_len = sample.response_length
    if resp_len == 0:
        sample.teacher_log_probs = torch.empty(0, dtype=torch.float32)
    else:
        sample.teacher_log_probs = torch.tensor(_student_rollout_lps(sample), dtype=torch.float32)

    if sample.metadata is None:
        sample.metadata = {}
    sample.metadata["opd_teacher_fallback"] = True
    sample.metadata["opd_teacher_fallback_reason"] = reason


def _encode_teacher_text(teacher_tok, text: str) -> list[int]:
    if getattr(teacher_tok, "is_fast", False):
        return [int(x) for x in teacher_tok(text, add_special_tokens=False)["input_ids"]]
    return [int(x) for x in teacher_tok.encode(text, add_special_tokens=False)]


def _normalize_messages(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    norm = []
    for msg in messages:
        mc = dict(msg)
        if mc.get("role") == "assistant":
            content = mc.get("content") or ""
            # Prevent chat templates from splitting literal "</think>" inside content when thinking was off.
            if mc.get("reasoning_content") is None and "</think>" in content:
                mc["reasoning_content"] = ""
        norm.append(mc)
    return norm


def _apply_teacher_template(args, teacher_tok, messages: list[dict[str, Any]], tools, add_generation_prompt: bool) -> str:
    template_kwargs = {"tokenize": False, "add_generation_prompt": add_generation_prompt}
    template_kwargs.update(getattr(args, "opd_teacher_chat_template_kwargs", None) or {})
    if tools is not None:
        template_kwargs["tools"] = tools
    try:
        return teacher_tok.apply_chat_template(messages, **template_kwargs)
    except TypeError:
        template_kwargs.pop("tools", None)
        return teacher_tok.apply_chat_template(messages, **template_kwargs)


def _trained_student_spans(sample: Sample) -> list[tuple[int, int]]:
    resp_len = sample.response_length
    mask = sample.loss_mask
    if not mask:
        return [(0, resp_len)] if resp_len > 0 else []
    spans = []
    i = 0
    n = min(resp_len, len(mask))
    while i < n:
        if mask[i]:
            j = i + 1
            while j < n and mask[j]:
                j += 1
            spans.append((i, j))
            i = j
        else:
            i += 1
    return spans


def _lcp_len(a: str, b: str) -> int:
    limit = min(len(a), len(b))
    i = 0
    while i < limit and a[i] == b[i]:
        i += 1
    return i


def _json_escaped_subspans(raw_str: str) -> list[bytes]:
    esc_str = json.dumps(raw_str, ensure_ascii=False)[1:-1]
    if esc_str == raw_str:
        b = raw_str.encode("utf-8")
        return [b] if b else []
    spans = []
    cur = []
    for ch in raw_str:
        ch_esc = json.dumps(ch, ensure_ascii=False)[1:-1]
        if ch_esc == ch:
            cur.append(ch)
        else:
            if cur:
                spans.append("".join(cur).encode("utf-8"))
                cur = []
    if cur:
        spans.append("".join(cur).encode("utf-8"))
    return spans


def _match_segment_bytes(
    s_bytes: bytes,
    s_pos: int,
    t_bytes: bytes,
    t_pos: int,
    seg_str: str | None,
    *,
    allow_json_escape: bool = False,
) -> tuple[int, int, list[tuple[int, int, int, int]]]:
    if not seg_str or not seg_str.strip("\n"):
        return s_pos, t_pos, []

    sb = seg_str.encode("utf-8")
    sp = s_bytes.find(sb, s_pos)
    tp = t_bytes.find(sb, t_pos)
    if sp >= 0 and tp >= 0:
        return sp + len(sb), tp + len(sb), [(sp, sp + len(sb), tp, tp + len(sb))]

    if not allow_json_escape:
        stripped = seg_str.strip("\n")
        if stripped:
            sb2 = stripped.encode("utf-8")
            sp2 = s_bytes.find(sb2, s_pos)
            tp2 = t_bytes.find(sb2, t_pos)
            if sp2 >= 0 and tp2 >= 0:
                sl, sr = sp2, sp2 + len(sb2)
                tl, tr = tp2, tp2 + len(sb2)
                while sl > s_pos and tl > t_pos and s_bytes[sl - 1 : sl] == b"\n" and t_bytes[tl - 1 : tl] == b"\n":
                    sl -= 1
                    tl -= 1
                while (
                    sr < len(s_bytes)
                    and tr < len(t_bytes)
                    and s_bytes[sr : sr + 1] == b"\n"
                    and t_bytes[tr : tr + 1] == b"\n"
                ):
                    sr += 1
                    tr += 1
                return sr, tr, [(sl, sr, tl, tr)]
    else:
        esc_str = json.dumps(seg_str, ensure_ascii=False)[1:-1]
        eb = esc_str.encode("utf-8")
        tp_esc = t_bytes.find(eb, t_pos)
        if sp >= 0 and tp_esc >= 0:
            subspans = []
            sc = sp
            tc = tp_esc
            for sub_b in _json_escaped_subspans(seg_str):
                sp_sub = s_bytes.find(sub_b, sc, sp + len(sb))
                tp_sub = t_bytes.find(sub_b, tc, tp_esc + len(eb))
                if sp_sub >= 0 and tp_sub >= 0:
                    subspans.append((sp_sub, sp_sub + len(sub_b), tp_sub, tp_sub + len(sub_b)))
                    sc = sp_sub + len(sub_b)
                    tc = tp_sub + len(sub_b)
            return sp + len(sb), tp_esc + len(eb), subspans

    return s_pos, t_pos, []


def _extract_turn_matched_spans(
    s_bytes: bytes,
    t_bytes: bytes,
    msg: dict[str, Any] | None,
) -> list[tuple[int, int, int, int]]:
    if msg is None:
        lcp = 0
        limit = min(len(s_bytes), len(t_bytes))
        while lcp < limit and s_bytes[lcp] == t_bytes[lcp]:
            lcp += 1
        return [(0, lcp, 0, lcp)] if lcp > 0 else []

    s_pos = 0
    t_pos = 0
    matched: list[tuple[int, int, int, int]] = []

    for seg in (msg.get("reasoning_content"), msg.get("content")):
        s_pos, t_pos, spans = _match_segment_bytes(s_bytes, s_pos, t_bytes, t_pos, seg, allow_json_escape=False)
        matched.extend(spans)

    for tc in msg.get("tool_calls") or []:
        fn = tc.get("function") or {}
        fn_name = fn.get("name")
        if fn_name:
            s_pos, t_pos, spans = _match_segment_bytes(
                s_bytes, s_pos, t_bytes, t_pos, str(fn_name), allow_json_escape=False
            )
            matched.extend(spans)
        fn_args = fn.get("arguments")
        if isinstance(fn_args, dict):
            for k, v in fn_args.items():
                s_pos, t_pos, spans = _match_segment_bytes(
                    s_bytes, s_pos, t_bytes, t_pos, str(k), allow_json_escape=False
                )
                matched.extend(spans)
                v_str = v if isinstance(v, str) else json.dumps(v, ensure_ascii=False)
                s_pos, t_pos, spans = _match_segment_bytes(
                    s_bytes, s_pos, t_bytes, t_pos, v_str, allow_json_escape=True
                )
                matched.extend(spans)
        elif isinstance(fn_args, str) and fn_args:
            s_pos, t_pos, spans = _match_segment_bytes(
                s_bytes, s_pos, t_bytes, t_pos, fn_args, allow_json_escape=True
            )
            matched.extend(spans)

    return matched


def _prepare_teacher_turns(args, sample: Sample) -> list[dict[str, Any]]:
    teacher_tok = args._cross_vocab_teacher_tok
    metadata = sample.metadata or {}
    key = getattr(args, "opd_prompt_messages_key", None) or "messages"
    raw_messages = metadata.get(key)
    if raw_messages is None and isinstance(sample.prompt, list):
        raw_messages = sample.prompt

    student_spans = _trained_student_spans(sample)
    if not student_spans:
        return []

    if isinstance(raw_messages, list):
        messages = _normalize_messages(raw_messages)
        tools = metadata.get("tools")
        asst_indices = [idx for idx, m in enumerate(messages) if m.get("role") == "assistant"]
        if len(asst_indices) == len(student_spans):
            turns = []
            for (st, en), m_idx in zip(student_spans, asst_indices, strict=True):
                pre_txt = _apply_teacher_template(
                    args, teacher_tok, messages[:m_idx], tools, add_generation_prompt=True
                )
                full_txt = _apply_teacher_template(
                    args, teacher_tok, messages[: m_idx + 1], tools, add_generation_prompt=False
                )
                lcp = _lcp_len(pre_txt, full_txt)
                if lcp == 0 and pre_txt:
                    dummy = [*messages[:m_idx], {"role": "assistant", "content": ""}]
                    dummy_txt = _apply_teacher_template(
                        args, teacher_tok, dummy, tools, add_generation_prompt=False
                    )
                    lcp = _lcp_len(dummy_txt, full_txt)
                full_ids = _encode_teacher_text(teacher_tok, full_txt)
                t_turn_offset = len(full_txt[:lcp].encode("utf-8"))
                turns.append(
                    {
                        "student_span": (st, en),
                        "message": messages[m_idx],
                        "full_ids": full_ids,
                        "t_turn_offset": t_turn_offset,
                    }
                )
            return turns

    # Fallback for single-turn or unparsed message prompts.
    prompt_messages = None
    if isinstance(raw_messages, list):
        prompt_messages = []
        for m in raw_messages:
            if m.get("role") == "assistant":
                break
            prompt_messages.append(m)
    elif isinstance(raw_messages, str):
        prompt_messages = raw_messages

    if prompt_messages is not None:
        if isinstance(prompt_messages, str):
            pre_txt = prompt_messages
        else:
            pre_txt = _apply_teacher_template(
                args, teacher_tok, prompt_messages, metadata.get("tools"), add_generation_prompt=True
            )
    elif isinstance(sample.prompt, str):
        pre_txt = sample.prompt
    else:
        raise TypeError(
            "Cross-vocabulary OPD requires a string prompt or chat messages in sample.prompt/metadata. "
            f"Got sample.prompt={type(sample.prompt).__name__}."
        )

    full_txt = pre_txt + (sample.response or "")
    full_ids = _encode_teacher_text(teacher_tok, full_txt)
    t_turn_offset = len(pre_txt.encode("utf-8"))
    st, en = student_spans[0][0], student_spans[-1][1]
    return [
        {
            "student_span": (st, en),
            "message": {"role": "assistant", "content": sample.response or ""},
            "full_ids": full_ids,
            "t_turn_offset": t_turn_offset,
        }
    ]


def _select_sequences_to_score(args, turns: list[dict[str, Any]]) -> tuple[list[list[int]], list[int], list[tuple[int, int]]]:
    """Deduplicate turn token sequences that are prefixes of later turns and compute logprob_start_len."""
    teacher_tok = args._cross_vocab_teacher_tok
    teacher_table = args._cross_vocab_teacher_bytes

    n_turns = len(turns)
    start_tok_indices = []
    for turn in turns:
        full_ids = turn["full_ids"]
        offset = turn["t_turn_offset"]
        cum = 0
        start_ti = 0
        for ti, tid in enumerate(full_ids):
            tb = _token_bytes(teacher_tok, teacher_table, tid)
            next_cum = cum + len(tb)
            if next_cum > offset:
                start_ti = ti
                break
            cum = next_cum
        else:
            start_ti = len(full_ids)
        start_tok_indices.append(start_ti)

    unique_seqs: list[list[int]] = []
    unique_min_start: list[int] = []
    turn_to_seq: list[tuple[int, int]] = [(-1, 0)] * n_turns

    # Walk from latest turn to earliest so any prefix turn reuses the longest covering turn sequence.
    for t_idx in range(n_turns - 1, -1, -1):
        seq = turns[t_idx]["full_ids"]
        start_ti = start_tok_indices[t_idx]
        matched_u = None
        for u_idx, u_seq in enumerate(unique_seqs):
            if len(u_seq) >= len(seq) and u_seq[: len(seq)] == seq:
                matched_u = u_idx
                break
        if matched_u is not None:
            unique_min_start[matched_u] = min(unique_min_start[matched_u], start_ti)
            turn_to_seq[t_idx] = (matched_u, start_ti)
        else:
            u_idx = len(unique_seqs)
            unique_seqs.append(seq)
            unique_min_start.append(start_ti)
            turn_to_seq[t_idx] = (u_idx, start_ti)

    # SGLang returns None for the first entry at logprob_start_len, so start at max(0, min_start - 1).
    logprob_starts = [max(0, ms - 1) for ms in unique_min_start]
    return unique_seqs, logprob_starts, turn_to_seq


async def reward_func_cross_vocab(args, sample: Sample, **kwargs):
    """Ask the SGLang teacher for logprobs on each assistant turn as the teacher sees it."""
    _load_cross_vocab_tokenizers(args)
    turns = _prepare_teacher_turns(args, sample)
    if not turns:
        return {"_cross_vocab_empty": True}

    unique_seqs, logprob_starts, turn_to_seq = _select_sequences_to_score(args, turns)
    batched = len(unique_seqs) > 1
    payload = {
        "input_ids": unique_seqs if batched else unique_seqs[0],
        "sampling_params": {
            "temperature": 0,
            "max_new_tokens": 0,
            "skip_special_tokens": False,
        },
        "return_logprob": True,
        "logprob_start_len": logprob_starts if batched else logprob_starts[0],
    }

    teacher_url = opd._teacher_url_for_sample(args, sample)
    result = await _post_teacher_json(args, teacher_url, payload, sample, "Cross-vocab OPD teacher request")
    if isinstance(result, dict) and result.get("_opd_teacher_fallback"):
        return result

    responses = result if isinstance(result, list) else [result]
    return {
        "responses": responses,
        "_cross_vocab_meta": {
            "turns": turns,
            "logprob_starts": logprob_starts,
            "turn_to_seq": turn_to_seq,
        },
    }


def _reconstruct_full_lps(resp_item: dict[str, Any], seq_len: int, start_len: int) -> list[float | None]:
    full_lps: list[float | None] = [None] * seq_len
    entries = (resp_item.get("meta_info") or {}).get("input_token_logprobs") or []
    for k, entry in enumerate(entries):
        pos = start_len + k
        if 0 <= pos < seq_len and entry is not None and entry[0] is not None:
            val = float(entry[0])
            if math.isfinite(val):
                full_lps[pos] = val
    return full_lps


def _align_turn_tokens(
    student_tok,
    student_table: list[bytes],
    student_turn_ids: list[int],
    teacher_tok,
    teacher_table: list[bytes],
    teacher_full_ids: list[int],
    teacher_full_lps: list[float | None],
    t_turn_offset: int,
    msg: dict[str, Any] | None,
) -> list[tuple[int, float]]:
    s_tok_bytes = [_token_bytes(student_tok, student_table, tid) for tid in student_turn_ids]
    t_tok_bytes = [_token_bytes(teacher_tok, teacher_table, tid) for tid in teacher_full_ids]

    s_bytes = b"".join(s_tok_bytes)
    t_full_bytes = b"".join(t_tok_bytes)
    t_bytes = t_full_bytes[t_turn_offset:]

    matched_spans = _extract_turn_matched_spans(s_bytes, t_bytes, msg)
    if not matched_spans:
        return []

    t_start_map: dict[int, int] = {}
    t_end_map: dict[int, int] = {}
    tcum = 0
    for ti, tb in enumerate(t_tok_bytes):
        if not tb:
            continue
        t_start_map[tcum] = ti
        tcum += len(tb)
        t_end_map[tcum] = ti

    updates: list[tuple[int, float]] = []
    scum = 0
    span_idx = 0
    n_spans = len(matched_spans)

    for si, sb in enumerate(s_tok_bytes):
        s0 = scum
        s1 = scum + len(sb)
        scum = s1
        if not sb:
            continue

        while span_idx < n_spans and matched_spans[span_idx][1] <= s0:
            span_idx += 1
        if span_idx >= n_spans:
            break

        ms0, ms1, mt0, _mt1 = matched_spans[span_idx]
        if s0 >= ms0 and s1 <= ms1:
            t0 = t_turn_offset + mt0 + (s0 - ms0)
            t1 = t_turn_offset + mt0 + (s1 - ms0)
            ti0 = t_start_map.get(t0)
            ti1 = t_end_map.get(t1)
            if ti0 is not None and ti1 is not None and ti1 >= ti0 and ti0 >= 1:
                lps = teacher_full_lps[ti0 : ti1 + 1]
                if all(lp is not None for lp in lps):
                    updates.append((si, float(sum(lps))))

    return updates


def post_process_cross_vocab(args, samples: list[Sample], teacher_results: list) -> None:
    """Store teacher logprobs on student response positions aligned to the teacher's turn rendering."""
    if any(not (isinstance(r, dict) and r.get("_opd_teacher_fallback")) for r in teacher_results if r is not None):
        _load_cross_vocab_tokenizers(args)
        student_tok = args._cross_vocab_student_tok
        teacher_tok = args._cross_vocab_teacher_tok
        student_table = args._cross_vocab_student_bytes
        teacher_table = args._cross_vocab_teacher_bytes

    for sample, reward in zip(samples, teacher_results, strict=True):
        resp_len = sample.response_length
        if resp_len == 0:
            sample.teacher_log_probs = torch.empty(0, dtype=torch.float32)
            continue

        if reward is None or (isinstance(reward, dict) and reward.get("_opd_teacher_fallback")):
            reason = "no_teacher" if reward is None else reward.get("_opd_teacher_fallback_reason", "teacher_failed")
            _use_student_log_probs_for_teacher(sample, reason)
            continue

        student_rollout_lps = _student_rollout_lps(sample)
        aligned_lps = list(student_rollout_lps)

        if isinstance(reward, dict) and reward.get("_cross_vocab_empty"):
            sample.teacher_log_probs = torch.tensor(aligned_lps, dtype=torch.float32)
            continue

        meta = reward["_cross_vocab_meta"]
        turns = meta["turns"]
        logprob_starts = meta["logprob_starts"]
        turn_to_seq = meta["turn_to_seq"]
        responses = reward["responses"]

        seq_full_lps = []
        for u_idx, resp_item in enumerate(responses):
            seq_idx_turns = [turns[t]["full_ids"] for t, (u, _) in enumerate(turn_to_seq) if u == u_idx]
            seq_len = max((len(s) for s in seq_idx_turns), default=0)
            seq_full_lps.append(_reconstruct_full_lps(resp_item, seq_len, logprob_starts[u_idx]))

        prompt_len = len(sample.tokens) - resp_len
        student_resp_ids = sample.tokens[prompt_len:]
        num_matched = 0

        for t_idx, turn in enumerate(turns):
            st, en = turn["student_span"]
            u_idx, _ = turn_to_seq[t_idx]
            full_ids = turn["full_ids"]
            full_lps = seq_full_lps[u_idx][: len(full_ids)]

            updates = _align_turn_tokens(
                student_tok,
                student_table,
                student_resp_ids[st:en],
                teacher_tok,
                teacher_table,
                full_ids,
                full_lps,
                turn["t_turn_offset"],
                turn["message"],
            )
            for rel_si, lp_val in updates:
                aligned_lps[st + rel_si] = lp_val
                num_matched += 1

        sample.teacher_log_probs = torch.tensor(aligned_lps, dtype=torch.float32)
        if sample.metadata is None:
            sample.metadata = {}
        sample.metadata["cross_vocab_token_overlap"] = num_matched / resp_len if resp_len > 0 else 0.0
